#!/usr/bin/env python3
import os, sys

repo = sys.argv[1]
out = sys.argv[2]
asm = os.path.join(out, "asm")
os.makedirs(asm, exist_ok=True)

def names(d):
    if not os.path.isdir(d):
        return set()
    return {f for f in os.listdir(d) if f.endswith(".h")}

gen_k = names(os.path.join(repo, "include/asm-generic"))
gen_u = names(os.path.join(repo, "include/uapi/asm-generic"))
arch_k = names(os.path.join(repo, "arch/x86/include/asm"))
arch_u = names(os.path.join(repo, "arch/x86/include/uapi/asm"))

for n in sorted(gen_k | gen_u):
    if n in arch_k or n in arch_u:
        continue
    with open(os.path.join(asm, n), "w") as f:
        f.write("#include <asm-generic/%s>\n" % n)
print("wrappers:", len(os.listdir(asm)))

